#include <iostream>
#include <iomanip>
#include "z4c/hyperboloidal/native_wormhole.hpp"
int main(){using N=z4c::hyperboloidal::NativeWormhole;N base(1./3.,2e-13,4,12,N::TransitionProfile::polynomial_c6);double m=1./3.,k=base.IsotropicScale();std::cout<<std::setprecision(17)<<"{\"k\":"<<k<<",\"affine_end\":"<<base.InnerRadius()<<",\"samples\":[";bool first=true;for(double r:{.2,base.InnerRadius(),.35,.4,.5,.56}){double jt=k,jr=k;if(r>base.InnerRadius()){double R=base.Point(r).areal,rho=(R-m+std::sqrt(R*(R-2*m)))/2,c=m/(2*rho),z=(R-4*m)/(8*m),S=0,SR=0;if(z>=1)S=1;else if(z>0){double t=std::min(z,1-z);double P=std::pow(t,7)*(1716+t*(-9009+t*(20020+t*(-24024+t*(16380+t*(-6006+924*t))))));S=z<=.5?P:1-P;SR=12012*std::pow(z*(1-z),6)/(8*m);}double A=std::sqrt(1-2*m/R+R*R*S*S),rp=R*A/r/(1-c*c),sig=rho+S*(R-rho),sigp=(1+SR*(1-c*c)*(R-rho)+S*((1-c*c)-1))*rp;jt=r/sig;jr=1/sigp;}double z=std::max(0.,std::min(1.,(.56-r)/.36)),s=std::pow(z,5)*(126+z*(-420+z*(540+z*(-315+70*z))));if(!first)std::cout<<',';first=false;std::cout<<"{\"r\":"<<r<<",\"inner_weight\":"<<s<<",\"J_radial\":"<<jr<<",\"J_tangential\":"<<jt<<'}';}std::cout<<"]}\n";}
